<template>
	<view class="uni-container">
		<uni-forms ref="form" :model="formData" validate-trigger="submit" err-show-type="toast">
			<uni-forms-item name="carNumber" label="车牌号">
				<uni-easyinput placeholder="车牌号" v-model="formData.carNumber"></uni-easyinput>
			</uni-forms-item>
			<uni-forms-item name="owner" label="车主姓名">
				<uni-easyinput placeholder="车主姓名" v-model="formData.owner"></uni-easyinput>
			</uni-forms-item>
			<uni-forms-item name="ownerphone" label="联系方式">
				<uni-easyinput placeholder="联系方式" v-model="formData.ownerphone"></uni-easyinput>
			</uni-forms-item>
			<uni-forms-item name="carType" label="车类型">
				<uni-easyinput placeholder="车类型；0五座，1SUV，2其他" v-model="formData.carType"></uni-easyinput>
			</uni-forms-item>
			<uni-forms-item name="brand" label="车辆品牌">
				<uni-easyinput placeholder="车辆品牌" v-model="formData.brand"></uni-easyinput>
			</uni-forms-item>
			<uni-forms-item name="engineNumber" label="发动机号">
				<uni-easyinput placeholder="发动机号" v-model="formData.engineNumber"></uni-easyinput>
			</uni-forms-item>
			<uni-forms-item name="frame" label="车架号">
				<uni-easyinput placeholder="车架号" v-model="formData.frame"></uni-easyinput>
			</uni-forms-item>
			<uni-forms-item name="insure" label="保险到期">
				<uni-datetime-picker return-type="timestamp" v-model="formData.insure"></uni-datetime-picker>
			</uni-forms-item>
			<uni-forms-item name="other" label="其他说明">
				<uni-easyinput placeholder="其他说明" v-model="formData.other"></uni-easyinput>
			</uni-forms-item>
			<view class="uni-button-group">
				<button type="primary" class="uni-button" @click="submit">提交</button>
			</view>
		</uni-forms>
	</view>
</template>

<script>
	import {
		validator
	} from '../../js_sdk/validator/car_info.js';

	const db = uniCloud.database();
	const dbCollectionName = 'car_info';

	function getValidator(fields) {
		let result = {}
		for (let key in validator) {
			if (fields.indexOf(key) > -1) {
				result[key] = validator[key]
			}
		}
		return result
	}



	export default {
		data() {
			let formData = {
				"carNumber": "",
				"owner": "",
				"ownerphone": "",
				"carType": "",
				"brand": "",
				"engineNumber": "",
				"frame": "",
				"insure": null,
				"other": ""
			}
			return {
				orderId: "",
				formData,
				formOptions: {},
				rules: {
					...getValidator(Object.keys(formData))
				}
			}
		},
		onLoad(e) {
			if (e.id) {
				const id = e.id
				this.formDataId = id
				this.getDetail(id)
				this.orderId = e.orderId
			}
		},
		onReady() {
			this.$refs.form.setRules(this.rules)
		},
		methods: {

			/**
			 * 验证表单并提交
			 */
			submit() {
				uni.showLoading({
					mask: true
				})
				this.$refs.form.validate().then((res) => {
					return this.submitForm(res)
				}).catch(() => {}).finally(() => {
					uni.hideLoading()
				})
			},

			/**
			 * 提交表单
			 */
			submitForm(value) {
				// 使用 clientDB 提交数据
				return db.collection(dbCollectionName).doc(this.formDataId).update(value).then((res) => {
					uni.showToast({
						icon: 'none',
						title: '修改成功'
					})
					this.getOpenerEventChannel().emit('refreshData', this.orderId)
					setTimeout(() => uni.navigateBack(), 500)
				}).catch((err) => {
					uni.showModal({
						content: err.message || '请求服务失败',
						showCancel: false
					})
				})
			},

			/**
			 * 获取表单数据
			 * @param {Object} id
			 */
			getDetail(id) {
				uni.showLoading({
					mask: true
				})
				db.collection(dbCollectionName).doc(id).field(
					"carNumber,owner,ownerphone,carType,brand,engineNumber,frame,insure,other").get().then((res) => {
					const data = res.result.data[0]
					if (data) {
						this.formData = data

					}
				}).catch((err) => {
					uni.showModal({
						content: err.message || '请求服务失败',
						showCancel: false
					})
				}).finally(() => {
					uni.hideLoading()
				})
			}
		}
	}
</script>

<style>
	.uni-container {
		padding: 15px;
	}

	.uni-input-border,
	.uni-textarea-border {
		width: 100%;
		font-size: 14px;
		color: #666;
		border: 1px #e5e5e5 solid;
		border-radius: 5px;
		box-sizing: border-box;
	}

	.uni-input-border {
		padding: 0 10px;
		height: 35px;

	}

	.uni-textarea-border {
		padding: 10px;
		height: 80px;
	}

	.uni-button-group {
		margin-top: 50px;
		/* #ifndef APP-NVUE */
		display: flex;
		/* #endif */
		justify-content: center;
	}

	.uni-button {
		width: 184px;
	}
</style>